"""Migration of the Meridian CRM 4.2 credit-hold sweep."""

from decimal import Decimal
from typing import Any


def _numeric(value: Any) -> Decimal:
    """Apply legacy NVL numeric behavior: missing or blank values are zero."""
    if value is None or value == "":
        return Decimal("0")
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def sweep(accounts: list[dict], orders: list[dict]) -> tuple[list[dict], list]:
    """Apply the nightly credit-hold sweep without mutating input rows."""
    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[str, Any]] = []

    exposures: dict[Any, Decimal] = {}
    for order in orders:
        if order.get("DEL_FLG") != "Y" and order.get("STAT_CD") == "I":
            acct_id = order.get("ACCT_ID")
            exposures[acct_id] = exposures.get(acct_id, Decimal("0")) + _numeric(
                order.get("TOT_AMT")
            )

    processable = [
        account
        for account in new_accounts
        if account.get("DEL_FLG") != "Y" and account.get("ACCT_TYP") == "C"
    ]

    for account in sorted(processable, key=lambda row: row.get("ACCT_ID")):
        acct_id = account.get("ACCT_ID")
        exposure = exposures.get(acct_id, Decimal("0"))
        credit_limit = _numeric(account.get("CRED_LIMIT"))

        if exposure > credit_limit and account.get("CRED_HOLD") != "Y":
            account["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", acct_id))

        if exposure <= credit_limit * Decimal("8") / Decimal("10") and account.get(
            "CRED_HOLD"
        ) == "Y":
            account["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", acct_id))

    return new_accounts, audits
